set -euo pipefail
conf=/opt/nifi/nifi-current/conf
sed -i -e 's|^nifi.web.https.port=.*|nifi.web.https.port=|' -e 's|^nifi.web.https.host=.*|nifi.web.https.host=|' -e 's|^nifi.web.http.host=.*|nifi.web.http.host=0.0.0.0|' -e 's|^nifi.web.http.port=.*|nifi.web.http.port=8080|' -e 's|^nifi.remote.input.secure=.*|nifi.remote.input.secure=false|' -e 's|^nifi.security.user.login.identity.provider=.*|nifi.security.user.login.identity.provider=|' -e 's|^nifi.security.keystore=.*|nifi.security.keystore=|' -e 's|^nifi.security.truststore=.*|nifi.security.truststore=|' "$conf/nifi.properties"
sed -i -e 's|^java.arg.2=.*|java.arg.2=-Xms256m|' -e 's|^java.arg.3=.*|java.arg.3=-Xmx768m|' "$conf/bootstrap.conf"
sed -i -e 's|^nifi.asset.manager.properties.directory=.*|nifi.asset.manager.properties.directory=./work/assets|' -e 's|^nifi.connector.asset.manager.properties.directory=.*|nifi.connector.asset.manager.properties.directory=./work/connector_assets|' -e 's|^nifi.nar.persistence.provider.properties.directory=.*|nifi.nar.persistence.provider.properties.directory=./work/nar_repository|' -e 's|^nifi.status.repository.questdb.persist.location=.*|nifi.status.repository.questdb.persist.location=./work/status_repository|' -e 's|^nifi.diagnostics.on.shutdown.directory=.*|nifi.diagnostics.on.shutdown.directory=./work/diagnostics|' -e 's|^nifi.nar.library.autoload.directory=.*|nifi.nar.library.autoload.directory=./nar_extensions|' "$conf/nifi.properties"
exec /opt/nifi/nifi-current/bin/nifi.sh run
